require("dotenv").config();

const {
  REST,
    Routes,
      SlashCommandBuilder,
        InteractionContextType,
          ChannelType,
            PermissionFlagsBits,
            } = require("discord.js");

            /**
             * Helper: build command safely
              * - Always returns .toJSON()
               */
               function cmd(builder) {
                 return builder.toJSON();
                 }

                 const commands = [
                   // =========================
                     // BASE COMMANDS
                       // =========================
                         cmd(
                             new SlashCommandBuilder()
                                   .setName("help")
                                         .setDescription("Shows a list of all commands and what they do.")
                                               .setContexts(
                                                       InteractionContextType.Guild,
                                                               InteractionContextType.BotDM,
                                                                       InteractionContextType.PrivateChannel
                                                                             )
                                                                               ),

                                                                                 cmd(
                                                                                     new SlashCommandBuilder()
                                                                                           .setName("status")
                                                                                                 .setDescription("Shows uptime + who made the bot.")
                                                                                                       .setContexts(
                                                                                                               InteractionContextType.Guild,
                                                                                                                       InteractionContextType.BotDM,
                                                                                                                               InteractionContextType.PrivateChannel
                                                                                                                                     )
                                                                                                                                       ),

                                                                                                                                         cmd(
                                                                                                                                             new SlashCommandBuilder()
                                                                                                                                                   .setName("ping")
                                                                                                                                                         .setDescription("Shows bot latency.")
                                                                                                                                                               .setContexts(
                                                                                                                                                                       InteractionContextType.Guild,
                                                                                                                                                                               InteractionContextType.BotDM,
                                                                                                                                                                                       InteractionContextType.PrivateChannel
                                                                                                                                                                                             )
                                                                                                                                                                                               ),

                                                                                                                                                                                                 cmd(
                                                                                                                                                                                                     new SlashCommandBuilder()
                                                                                                                                                                                                           .setName("crazy")
                                                                                                                                                                                                                 .setDescription("Send the crazy copypasta with buttons (rate-limited).")
                                                                                                                                                                                                                       .addIntegerOption((o) =>
                                                                                                                                                                                                                               o
                                                                                                                                                                                                                                         .setName("times")
                                                                                                                                                                                                                                                   .setDescription("How many cycles (1-3)")
                                                                                                                                                                                                                                                             .setRequired(false)
                                                                                                                                                                                                                                                                   )
                                                                                                                                                                                                                                                                         .setContexts(
                                                                                                                                                                                                                                                                                 InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                         InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                 InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                       )
                                                                                                                                                                                                                                                                                                         ),

                                                                                                                                                                                                                                                                                                           cmd(
                                                                                                                                                                                                                                                                                                               new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                     .setName("compliment")
                                                                                                                                                                                                                                                                                                                           .setDescription("Send a random compliment.")
                                                                                                                                                                                                                                                                                                                                 .addUserOption((opt) =>
                                                                                                                                                                                                                                                                                                                                         opt
                                                                                                                                                                                                                                                                                                                                                   .setName("user")
                                                                                                                                                                                                                                                                                                                                                             .setDescription("Who to compliment (server only)")
                                                                                                                                                                                                                                                                                                                                                                       .setRequired(false)
                                                                                                                                                                                                                                                                                                                                                                             )
                                                                                                                                                                                                                                                                                                                                                                                   .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                           InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                   InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                           InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                 )
                                                                                                                                                                                                                                                                                                                                                                                                                   ),

                                                                                                                                                                                                                                                                                                                                                                                                                     cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                         new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                               .setName("cat")
                                                                                                                                                                                                                                                                                                                                                                                                                                     .setDescription("Get a random chaotic cat picture.")
                                                                                                                                                                                                                                                                                                                                                                                                                                           .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                                                                                   InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                                                                           InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                             cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .setName("mimic")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .setDescription("The bot mimics you in SpOnGeBoB cAsE.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .addStringOption((opt) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           opt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .setName("text")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .setDescription("The text to mimic")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .setRequired(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .setName("roast")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .setDescription("The bot roasts someone.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .addUserOption((opt) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     opt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .setName("user")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .setDescription("Who to roast")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .setRequired(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   // DEPLOY CHANNEL COMMANDS (Guild only)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // (Permissions here are optional; you already enforce in index.js too.)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .setName("set_deploy_channel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .setDescription("Set the channel for deployment updates.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .addChannelOption((opt) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       opt
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .setName("channel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setDescription("Channel to post deploy updates in")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .setRequired(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setContexts(InteractionContextType.Guild)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // Optional: restrict in Discord UI (still keep your index.js checks)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .setName("show_deploy_channel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setDescription("Show the current deployment updates channel.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .setContexts(InteractionContextType.Guild)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .setName("reset_deploy_channel")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setDescription("Reset the deployment updates channel for this server.")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .setContexts(InteractionContextType.Guild)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // TODO SYSTEM (Global TODO list, but command is usable anywhere)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // =========================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setName("todo_add")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .setDescription("Add a TODO item (global list).")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .addStringOption((o) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               o
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .setName("text")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .setDescription("What needs to be done?")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .setRequired(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .setName("todo_list")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setDescription("List TODO items (global list).")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ),

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   cmd(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       new SlashCommandBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .setName("todo_done")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .setDescription("Mark a TODO as done (global list).")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .addIntegerOption((o) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 o
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setName("id")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .setDescription("The TODO id from /todo_list")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .setRequired(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .setContexts(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   InteractionContextType.Guild,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           InteractionContextType.BotDM,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   InteractionContextType.PrivateChannel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // ✅ BEST APPROACH: never send holes/undefined to Discord
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const safeCommands = commands.filter(Boolean);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           // Optional: quick sanity log (helps catch weirdness immediately)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           console.log("Registering commands:", safeCommands.map((c) => c.name));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const token = process.env.BOT_TOKEN;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const appId = process.env.APP_ID;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (!token || !appId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             console.error("❌ Missing BOT_TOKEN or APP_ID in environment.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               process.exit(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const rest = new REST({ version: "10" }).setToken(token);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               (async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     await rest.put(Routes.applicationCommands(appId), { body: safeCommands });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         console.log("✅ Global commands registered.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             process.exit(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   console.error("❌ Failed to register commands:", err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       process.exit(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         })();